let researchChart=null,researchResize=null,chartMemory=null,chartPayload=null,chartRead=null;
const chartOptions={short:true,mid:true,ma60:true,bands:true,volume:true,wyLevels:false};
function destroyResearchChart(){chartRead=null;if(researchChart){const range=researchChart.timeScale().getVisibleLogicalRange();if(range&&chartPayload)chartMemory={key:chartPayload.key,range};researchChart.remove();researchChart=null}if(researchResize){researchResize.disconnect();researchResize=null}}
function candleChart(result){
 const closedDates=new Set(series(state.code,{includeLive:false}).map(b=>b.date)),all=series(state.code).map(b=>({...b,completed:closedDates.has(b.date)})),bars=all.filter(b=>b.date>=bt.start&&b.date<=bt.end);
 const provisional=all.some(b=>b.completed===false)?E.signals(all,{enhanced:bt.enhanced}).filter(s=>s.provisional&&s.date>=bt.start&&s.date<=bt.end):[];
 const signals=[...result.signals,...provisional].sort((a,b)=>a.date.localeCompare(b.date));
 chartPayload={all,bars,signals,wyPoints:result.wyckoff?.model.points||[],key:state.code+':'+bt.start+':'+bt.end};return `<div class="chart-controls"><div class="actions"><button class="btn small" onclick="chartZoom(.7)" aria-label="放大K线">＋</button><button class="btn small" onclick="chartZoom(1.4)" aria-label="缩小K线">−</button><button class="btn small" onclick="chartFit()">适应区间</button><button class="btn small" onclick="chartLatest()">最近60根</button></div><div class="chart-toggles">${[['short','SHORTL'],['mid','MIDL'],['ma60','MA60'],['bands','布林带'],['volume','成交量'],...(bt.wyckoff?[['wyLevels','威科夫区间']]:[])].map(([key,label])=>`<label><input type="checkbox" ${chartOptions[key]?'checked':''} onchange="chartOptions.${key}=this.checked;rebuildChart()">${label}</label>`).join('')}</div></div><div id="chart-readout" class="chart-readout" role="status" aria-live="polite">拖动平移 · 滚轮/双指缩放 · 点击或悬浮查看OHLC与信号</div><div id="candle-chart" class="html5-chart" role="img" aria-label="可缩放、平移的交互K线图"></div><div id="chart-window" class="chart-window"></div><div class="chart-footer"><span>选定区间${esc(bt.start)} — ${esc(bt.end)} · ${bars.length}根K线${bars.some(b=>b.completed===false)?' · 含盘中未确认K线':''}</span><a href="https://www.tradingview.com/lightweight-charts/" target="_blank" rel="noopener">TradingView Lightweight Charts™</a></div><details class="chart-data-table"><summary>查看可访问的K线数据表</summary><div class="table-wrap"><table><thead><tr><th>日期 / 状态</th><th>开 / 高 / 低 / 收</th><th>成交量</th></tr></thead><tbody>${bars.slice(-100).reverse().map(b=>`<tr><td>${b.date} ${b.completed===false?'盘中':'收盘'}</td><td>${num(b.open,3)} / ${num(b.high,3)} / ${num(b.low,3)} / ${num(b.close,3)}</td><td>${num(b.vol,0)}</td></tr>`).join('')}</tbody></table></div></details>`}
function mountResearchChart(){const host=document.querySelector('#candle-chart');if(!host||!chartPayload)return;if(!chartPayload.bars.length){host.innerHTML='<div class="empty">所选日期内没有K线。</div>';return}if(!window.LightweightCharts){host.innerHTML='<div class="empty">图表组件加载失败，请重新启动完整本地运行包。</div>';return}const {all,bars,signals,key,wyPoints}=chartPayload,LC=LightweightCharts,minMove=asset().type==='etf'?.001:.01,precision=asset().type==='etf'?3:2;
 const palette=getComputedStyle(document.documentElement),surface=palette.getPropertyValue('--surface').trim()||'#ffffff',muted=palette.getPropertyValue('--muted').trim()||'#728096',grid=palette.getPropertyValue('--chart-grid').trim()||'#edf1f4',lineColor=palette.getPropertyValue('--line').trim()||'#e7edf1';
 researchChart=LC.createChart(host,{width:host.clientWidth,height:410,layout:{background:{type:'solid',color:surface},textColor:muted,fontFamily:'system-ui, sans-serif',fontSize:11,attributionLogo:true},grid:{vertLines:{color:grid},horzLines:{color:grid}},rightPriceScale:{borderColor:lineColor,scaleMargins:{top:.1,bottom:.25}},timeScale:{borderColor:lineColor,timeVisible:false,rightOffset:4},crosshair:{mode:LC.CrosshairMode.Normal},handleScroll:{mouseWheel:true,pressedMouseMove:true,horzTouchDrag:true,vertTouchDrag:false},handleScale:{mouseWheel:true,pinch:true,axisPressedMouseMove:true},localization:{locale:'zh-CN'}});
 const candles=researchChart.addSeries(LC.CandlestickSeries,{upColor:'#df665e',downColor:'#219783',wickUpColor:'#df665e',wickDownColor:'#219783',borderVisible:false,priceFormat:{type:'price',precision,minMove}});candles.setData(bars.map(b=>({time:b.date,open:b.open,high:b.high,low:b.low,close:b.close,...(b.completed===false?{borderColor:'#bf791e',wickColor:'#bf791e'}:{})})));
 const map=new Map(E.indicator(all).map(b=>[b.date,b]));function line(field,color,dashed=false){const s=researchChart.addSeries(LC.LineSeries,{color,lineWidth:1,priceLineVisible:false,lastValueVisible:false,crosshairMarkerVisible:false,...(dashed?{lineStyle:2}:{})});s.setData(bars.map(b=>{const i=map.get(b.date);const value=field==='upper'?i.ma20*(1+i.width/2):field==='lower'?i.ma20*(1-i.width/2):i[field];return {time:b.date,value}}))}
 if(chartOptions.short)line('short','#c5a262');if(chartOptions.mid)line('mid','#6b8db9');if(chartOptions.ma60)line('ma60','#997ba9',true);if(chartOptions.bands){line('upper','#a8b8bd',true);line('lower','#a8b8bd',true)}if(chartOptions.volume){const v=researchChart.addSeries(LC.HistogramSeries,{priceFormat:{type:'volume'},priceScaleId:'volume',priceLineVisible:false,lastValueVisible:false});v.priceScale().applyOptions({scaleMargins:{top:.82,bottom:0},visible:false});v.setData(bars.map(b=>({time:b.date,value:b.vol,color:b.close>=b.open?'#df665e55':'#21978355'})))}
 if(chartOptions.wyLevels&&wyPoints.length){
  const points=new Map(wyPoints.map(p=>[p.date,p]));
  for(const [field,color] of [['support','#527ce4'],['resistance','#cc903b']]){
   const level=researchChart.addSeries(LC.LineSeries,{color,lineWidth:1,lineStyle:2,priceLineVisible:false,lastValueVisible:false,crosshairMarkerVisible:false});
   level.setData(bars.flatMap(b=>E.valid(points.get(b.date)?.[field])?[{time:b.date,value:points.get(b.date)[field]}]:[]));
  }
 }
 LC.createSeriesMarkers(candles,backtestMarkers(signals,muted,palette.getPropertyValue('--orange').trim()||'#bf791e',palette.getPropertyValue('--green').trim()||'#087f74',palette.getPropertyValue('--red').trim()||'#df554e'));
 const live=bars.find(b=>b.completed===false);if(live)candles.createPriceLine({price:live.close,color:'#bf791e',lineWidth:1,lineStyle:2,axisLabelVisible:true,title:'盘中未确认'});
 const read=param=>{if(!param.time)return;const date=typeof param.time==='string'?param.time:typeof param.time==='object'?param.time.year+'-'+String(param.time.month).padStart(2,'0')+'-'+String(param.time.day).padStart(2,'0'):new Date(param.time*1000).toISOString().slice(0,10);const b=bars.find(b=>b.date===date);if(!b)return;const index=all.findIndex(v=>v.date===b.date),prev=all[index-1]?.close,pct=prev?(b.close/prev-1)*100:null,sig=signals.find(s=>s.date===b.date);document.querySelector('#chart-readout').textContent=`${b.date} ${b.completed===false?'盘中未确认':'收盘'}  开 ${num(b.open,precision)}  高 ${num(b.high,precision)}  低 ${num(b.low,precision)}  收 ${num(b.close,precision)}  昨收涨跌 ${change(pct)}  量 ${num(b.vol,0)}${sig?'  '+(sig.type==='buy'?'笑脸 '+sig.grade:'哭脸')+' · '+sig.reason:''}`};chartRead=read;researchChart.subscribeCrosshairMove(read);researchChart.subscribeClick(read);
 researchChart.timeScale().subscribeVisibleLogicalRangeChange(range=>{if(!range)return;const first=bars[Math.max(0,Math.min(bars.length-1,Math.floor(range.from)))],last=bars[Math.max(0,Math.min(bars.length-1,Math.ceil(range.to)))];const el=document.querySelector('#chart-window');if(el)el.textContent=`当前视窗 ${first?.date||'—'} — ${last?.date||'—'}`});if(chartMemory?.key===key)researchChart.timeScale().setVisibleLogicalRange(chartMemory.range);else researchChart.timeScale().fitContent();researchResize=new ResizeObserver(()=>{if(researchChart)researchChart.applyOptions({width:host.clientWidth})});researchResize.observe(host);read({time:bars.at(-1).date});
}
function chartZoom(factor){if(!researchChart)return;const r=researchChart.timeScale().getVisibleLogicalRange();if(!r)return;const center=(r.from+r.to)/2,half=Math.max(3,(r.to-r.from)*factor/2);researchChart.timeScale().setVisibleLogicalRange({from:center-half,to:center+half})}
function chartFit(){if(researchChart)researchChart.timeScale().fitContent()}
function chartLatest(){if(researchChart)researchChart.timeScale().setVisibleLogicalRange({from:Math.max(0,chartPayload.bars.length-60),to:chartPayload.bars.length+3})}
function rebuildChart(){destroyResearchChart();mountResearchChart()}
function changeBacktestDate(key,value){bt[key]=value;bt.rangeTouched=true;chartMemory=null;render()}

function backtestMarkers(signals,muted,orange,green,red){
 return signals.flatMap(s=>{
  const supported=!!s.wyckoff&&!s.provisional&&!s.filtered,position=s.type==='buy'||supported?'belowBar':'aboveBar';
  const face={time:s.date,position,color:s.filtered?muted:s.provisional?orange:s.type==='buy'?green:red,shape:s.type==='buy'?'arrowUp':'arrowDown',text:(s.provisional?'盘中 ':'')+(s.type==='buy'?'☺ '+s.grade:'☹')+(s.filtered?' 过滤':'')};
  return supported?[face,{time:s.date,position:'belowBar',color:'#397eff',shape:'circle',size:0,text:'▲'}]:[face];
 });
}
function focusBacktestDate(date){
 const i=chartPayload?.bars.findIndex(b=>b.date===date);if(!researchChart||!(i>=0))return;
 researchChart.timeScale().setVisibleLogicalRange({from:Math.max(-.5,i-9),to:Math.min(chartPayload.bars.length+1,i+9)});
 document.getElementById('candle-chart')?.scrollIntoView({block:'center'});chartRead?.({time:date});
}
